seen=set(); comps=[]
for r in range(20):
 for c in range(29):
  v=grid[r][c]
  if v==6 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   p=q.pop();cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=p[0]+dr,p[1]+dc
    if 0<=rr<20 and 0<=cc<29 and (rr,cc) not in seen and grid[rr][cc]==v:
     seen.add((rr,cc));q.append((rr,cc))
  rs=[x for x,y in cells];cs=[y for x,y in cells]
  comps.append((v,len(cells),(min(rs),max(rs),min(cs),max(cs)),(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)))
print(comps)
